/**
 * Neo Synth (synthetic data studio) client tool.
 *
 * The agent drives `/synth` through this one tool, the same way Neo ME
 * drives `/modernize` through `modernization_control`. The agent discovers
 * the data model (schemas, relations, rules, flows) by reading the code;
 * the studio generates, validates, exports and previews the data itself,
 * deterministically, in the browser.
 */

export const SYNTH_CONTROL_TOOL_NAME = "synth_control";

/** Action discriminator generated by the SDK for a client-defined tool. */
export const SYNTH_CONTROL_ACTION_KIND =
  `ClientAction_${SYNTH_CONTROL_TOOL_NAME}` as const;

/**
 * Prefix on every receipt posted back into the conversation after a command
 * ran in the browser (and on user answers to choice cards). Hidden from the
 * transcript by `isSynthReceiptEvent`.
 */
export const SYNTH_RESULT_PREFIX = "[synth result] ";

/**
 * Commands the agent may issue. The complete set ships at once: the
 * agent-server caches a client tool's schema per tool NAME for its whole
 * life (see `src/constants/onboarding-control.ts`). Per-command payload
 * shapes are answered by `describe`, never encoded in the schema.
 */
export const SYNTH_CONTROL_COMMANDS = [
  // Orientation: project, model so far, scenarios, runs, payload shapes,
  // schema files found in the workspace.
  "describe",
  // Parse schema files the studio understands (Prisma, SQL DDL, JSON
  // Schema, OpenAPI) straight from the workspace into the model.
  "import_schema",
  // Entities and fields the agent read from ORM models, migrations, types
  // or API handlers, with evidence.
  "record_model",
  // Business rules the code enforces (implies / compare / unique together /
  // range / pattern); the generator honours them, the validator checks them.
  "record_rules",
  // Data flows: where each entity is produced and consumed.
  "record_flows",
  // Value distributions observed in real data (labels and statistics only).
  "record_profile",
  // A question rendered as selectable cards; the user's choice comes back as
  // a receipt the agent must wait for.
  "ask_choice",
  // Named scenarios (counts per entity, overrides, edge cases).
  "set_scenarios",
  // Generate + validate + export + write to the workspace. The studio does
  // the work; the receipt carries the validation result and the paths.
  "generate",
  // Proof the data was used: loaded into a database, tests run on it.
  "report_verification",
  // A line in the live log (no receipt).
  "log",
  // Final summary; refused until a valid, verified run exists.
  "complete",
] as const;

export type SynthControlCommand = (typeof SYNTH_CONTROL_COMMANDS)[number];

export const SYNTH_PROJECT_STATUSES = [
  "intake",
  "discovering",
  "modeling",
  "interviewing",
  "ready",
  "generating",
  "verifying",
  "done",
  "failed",
] as const;
export type SynthProjectStatus = (typeof SYNTH_PROJECT_STATUSES)[number];
